import { getContext, setContext } from 'svelte'
import type { CheckoutContext, CheckoutLineContext } from './types.js'

const CHECKOUT = Symbol('checkout')
const CHECKOUT_LINE = Symbol('checkout-line')

export function setCheckoutContext(ctx: CheckoutContext) {
	setContext(CHECKOUT, ctx)
}
export function getCheckoutContext(): CheckoutContext {
	const ctx = getContext<CheckoutContext>(CHECKOUT)
	if (!ctx) throw new Error('Checkout.* must be used within <Checkout.Root>')
	return ctx
}
export function getCheckoutContextOptional(): CheckoutContext | null {
	return getContext<CheckoutContext>(CHECKOUT) ?? null
}
export function setCheckoutLineContext(ctx: CheckoutLineContext) {
	setContext(CHECKOUT_LINE, ctx)
}
export function getCheckoutLineContext(): CheckoutLineContext {
	const ctx = getContext<CheckoutLineContext>(CHECKOUT_LINE)
	if (!ctx) throw new Error('Checkout line parts must be used within <Checkout.Item>')
	return ctx
}

import type { StoreOrder, StoreCart } from '@medusajs/types'
import type { UpdateAddress, AuthorizePayment } from './types'

export type PlaceOrderSteps = {
	updateAddress: UpdateAddress | null
	hasShipping: () => boolean
	authorizePayment: AuthorizePayment | null
	completeCart: () => Promise<StoreOrder | StoreCart | null>
}

function isOrder(result: unknown): result is StoreOrder {
	// The SDK's completeCart unwraps Medusa's `{type:'order',order}` / `{type:'cart',cart}` to the
	// order-or-cart payload. Medusa prefixes ids by entity type, so a completed order is `order_…`
	// and a failed-completion cart is `cart_…` — a reliable discriminant on the unwrapped payload.
	return !!result && typeof (result as { id?: unknown }).id === 'string' && (result as { id: string }).id.startsWith('order_')
}

/** Ordered place-order sequence with guards. Pure: all IO is injected. */
export async function runPlaceOrder(steps: PlaceOrderSteps): Promise<{ order: StoreOrder } | { error: unknown }> {
	try {
		if (steps.updateAddress) await steps.updateAddress()
		if (!steps.hasShipping()) return { error: new Error('No delivery method selected') }
		if (steps.authorizePayment) {
			const r = await steps.authorizePayment()
			if (!r.ok) return { error: r.error ?? new Error('Payment authorization failed') }
		}
		const result = await steps.completeCart()
		if (!result) return { error: new Error('Failed to complete the order') }
		if (!isOrder(result)) return { error: (result as any).errors ?? new Error('Cart could not be completed') }
		return { order: result as StoreOrder }
	} catch (e) {
		return { error: e }
	}
}

/**
 * Pick the payment provider to render: the first of the cart region's `available` provider ids that
 * this checkout `supported`s. Returns undefined when the region offers no supported provider (caller
 * then renders nothing + warns). Structured so a future multi-provider selector is additive.
 */
export function resolveProvider(available: string[], supported: string[]): string | undefined {
	return available.find(id => supported.includes(id))
}

/** Which checkout body renders a provider id. The whole Stripe FAMILY (`pp_stripe-*`: card, iDEAL,
 *  Bancontact, …) routes to the Stripe body; Braintree to the Braintree body; anything else = null. */
export type CheckoutProviderKind = 'stripe' | 'braintree'
export function classifyProvider(id: string): CheckoutProviderKind | null {
	if (id.startsWith('pp_stripe')) return 'stripe'
	if (id === 'pp_braintree_braintree') return 'braintree'
	return null
}

/** First available provider this checkout can render, with the body that renders it. */
export function resolveCheckoutProvider(available: string[]): { id: string; kind: CheckoutProviderKind } | null {
	for (const id of available) {
		const kind = classifyProvider(id)
		if (kind) return { id, kind }
	}
	return null
}

export function resolveRedirect(redirectTo: string | ((order: StoreOrder) => string) | undefined, order: StoreOrder): string | undefined {
	if (!redirectTo) return undefined
	return typeof redirectTo === 'function' ? redirectTo(order) : redirectTo
}

/**
 * Find a provider's payment-session `data` in an initiate-session response. Medusa returns the
 * payment-collection with its sessions; each session's `data` is the raw provider payload (the
 * Braintree client-token blob, or the Stripe PaymentIntent). Falls back to the first session.
 */
function getProviderSessionData(session: any, providerId: string): any | undefined {
	const sessions = session?.payment_collection?.payment_sessions
	if (!Array.isArray(sessions)) return undefined
	const s = sessions.find((ps: any) => ps?.provider_id === providerId) ?? sessions[0]
	return s?.data
}

/** Extract the Braintree client_token from an initiate-session response. */
export function getBraintreeClientToken(session: any, providerId: string): string | undefined {
	return getProviderSessionData(session, providerId)?.client_token
}

/**
 * Extract the Stripe client_secret from an initiate-session response. The Stripe provider stores the
 * full PaymentIntent as the session `data` (verified: `stripe-base.getStatus` → `{ data: intent }`),
 * so the secret lives at `…payment_sessions[].data.client_secret`.
 */
export function getStripeClientSecret(session: any, providerId: string): string | undefined {
	return getProviderSessionData(session, providerId)?.client_secret
}

/** Which elements:false payment UI a Stripe provider id maps to (null = not yet wired). */
export function resolveStripeMethod(providerId: string): 'card' | 'ideal' | null {
	if (providerId === 'pp_stripe_stripe') return 'card'
	if (providerId === 'pp_stripe-ideal_stripe') return 'ideal'
	return null
}

/** Stripe `billing_details` built from the cart's shipping address (for confirm<Method>Payment). */
export function cartBillingDetails(cart: any): {
	name?: string
	email?: string
	phone?: string
	address?: {
		line1?: string
		line2?: string
		city?: string
		postal_code?: string
		state?: string
		country?: string
	}
} {
	const s = cart?.shipping_address
	if (!cart) return {}
	const name = [s?.first_name, s?.last_name].filter(Boolean).join(' ') || undefined
	return {
		name,
		email: cart?.email || undefined,
		phone: s?.phone || undefined,
		address: s
			? {
					line1: s.address_1 || undefined,
					line2: s.address_2 || undefined,
					city: s.city || undefined,
					postal_code: s.postal_code || undefined,
					state: s.province || undefined,
					country: s.country_code || undefined
				}
			: undefined
	}
}

/** Map Medusa shipping options to the Stripe Express Checkout shipping-rate shape. */
export function medusaShippingToStripeRates(options: any[]): { id: string; displayName: string; amount: number }[] {
	return (options ?? []).map(o => ({ id: o.id, displayName: o.name, amount: o.amount ?? 0 }))
}

/** Map a wallet's billing/shipping details (Express Checkout) to a Medusa cart-update payload. */
export function walletAddressToMedusa(
	billing: any,
	shipping?: { name?: string; address?: any }
): { email?: string; shipping_address?: any; billing_address?: any } {
	const toAddr = (name?: string, a?: any) => {
		if (!a) return undefined
		const [first_name, ...rest] = String(name ?? '')
			.trim()
			.split(' ')
		return {
			first_name: first_name || undefined,
			last_name: rest.join(' ') || undefined,
			phone: billing?.phone || undefined,
			address_1: a.line1 || undefined,
			address_2: a.line2 || undefined,
			city: a.city || undefined,
			province: a.state || undefined,
			postal_code: a.postal_code || undefined,
			country_code: a.country ? String(a.country).toLowerCase() : undefined
		}
	}
	return {
		email: billing?.email || undefined,
		shipping_address: toAddr(shipping?.name ?? billing?.name, shipping?.address ?? billing?.address),
		billing_address: toAddr(billing?.name, billing?.address)
	}
}

import type { Appearance } from '@stripe/stripe-js'

/**
 * Build a Stripe Elements `appearance` from the app's shadcn design tokens.
 *
 * Stripe Elements render inside an iframe and cannot resolve the parent document's CSS custom
 * properties, so we pass CONCRETE values read off the document root. Crucially, Stripe's appearance
 * API only accepts HEX / rgb() / hsl() colors — NOT Tailwind v4's `oklch(...)` — so color tokens are
 * rasterized to rgb through a 1px `<canvas>` (see `domCssVarResolver`). We can NOT use
 * `getComputedStyle(probe).color`: modern browsers serialize computed colors back as `oklab(...)` /
 * `oklch(...)`, which Stripe (and Braintree) reject. Non-color tokens (radius, font) pass through raw.
 * The resolver is injectable so the mapping is unit-testable without a DOM.
 */

/** Resolve a CSS custom property. `asColor` converts the value to an rgb() string for Stripe. */
export type CssVarResolver = (name: string, asColor?: boolean) => string

/** Default resolver: read computed `:root` custom properties; rasterize colors to rgb via a canvas. */
export function domCssVarResolver(): CssVarResolver {
	const rootStyles = getComputedStyle(document.documentElement)
	// A 1px canvas rasterizes ANY CSS color (oklch/oklab/hsl/hex) to concrete sRGB bytes. We do NOT use
	// `getComputedStyle(probe).color` — modern browsers serialize computed colors back as
	// `oklab(...)`/`oklch(...)`, which Stripe/Braintree reject; the canvas always yields rgb.
	const canvas = document.createElement('canvas')
	canvas.width = canvas.height = 1
	const ctx = canvas.getContext('2d')
	return (name, asColor = false) => {
		const raw = rootStyles.getPropertyValue(name).trim()
		if (!raw || !asColor || !ctx) return raw
		ctx.clearRect(0, 0, 1, 1)
		ctx.fillStyle = '#000' // fallback kept if `raw` is an unparseable color (setter ignores it)
		ctx.fillStyle = raw
		ctx.fillRect(0, 0, 1, 1)
		const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data
		return a === 255 ? `rgb(${r}, ${g}, ${b})` : `rgba(${r}, ${g}, ${b}, ${+(a / 255).toFixed(3)})`
	}
}

export interface StripeAppearanceOptions {
	/** Override the resolver (tests inject a fake; browser defaults to the DOM). */
	resolve?: CssVarResolver
	/** Stripe base theme to layer tokens over. */
	theme?: Appearance['theme']
	/**
	 * Opaque input-surface color for `colorBackground` — pass `resolveInputSurface()` so Stripe's fields
	 * match the shadcn inputs' lift. Falls back to `--background` when omitted (e.g. unit tests, no DOM).
	 */
	inputSurface?: string
}

export function buildStripeAppearance(opts: StripeAppearanceOptions = {}): Appearance {
	const resolve = opts.resolve ?? domCssVarResolver()
	const color = (name: string): string | undefined => resolve(name, true) || undefined
	const raw = (name: string): string | undefined => resolve(name, false) || undefined

	const variables = pruneUndefined({
		colorPrimary: color('--primary'),
		colorBackground: opts.inputSurface || color('--background'),
		colorText: color('--foreground'),
		colorTextSecondary: color('--muted-foreground'),
		colorDanger: color('--destructive'),
		borderRadius: raw('--radius'),
		fontFamily: raw('--font-sans')
	})

	// Rule values must be concrete strings (no `undefined`), so only add a property when it resolves.
	const border = color('--border')
	const ring = color('--ring')
	const inputRule: Record<string, string> = { boxShadow: 'none' }
	if (border) inputRule.border = `1px solid ${border}`
	const focusRule: Record<string, string> = {}
	if (ring) {
		focusRule.border = `1px solid ${ring}`
		focusRule.boxShadow = `0 0 0 3px ${ring}`
	}

	return {
		theme: opts.theme ?? 'stripe',
		variables,
		rules: { '.Input': inputRule, '.Input:focus': focusRule }
	}
}

function pruneUndefined<T extends Record<string, unknown>>(obj: T): T {
	for (const k of Object.keys(obj)) if (obj[k] === undefined) delete obj[k]
	return obj
}

/**
 * The OPAQUE color a shadcn `<input>` visually shows on this page — its translucent `bg-input/30`
 * lift composited over `--background`. Iframe / shadow-DOM surfaces (Braintree hosted fields, Stripe
 * Elements) can't paint a translucent fill (it wouldn't cover the browser's default white form
 * background), so they need this opaque equivalent to match the plain shadcn inputs beside them.
 * Reads a hidden probe carrying the REAL input classes (so it tracks whatever lift the theme defines),
 * then composites lift-over-background on a 1px canvas — which handles oklch/oklab AND the alpha blend.
 */
export function resolveInputSurface(): string {
	const bgRaw = getComputedStyle(document.documentElement).getPropertyValue('--background').trim()
	const probe = document.createElement('div')
	probe.className = 'bg-transparent dark:bg-input/30'
	probe.style.cssText = 'position:absolute;opacity:0;pointer-events:none'
	document.body.appendChild(probe)
	const liftRaw = getComputedStyle(probe).backgroundColor
	probe.remove()
	const canvas = document.createElement('canvas')
	canvas.width = canvas.height = 1
	const ctx = canvas.getContext('2d')
	if (!ctx) return bgRaw || 'rgb(255, 255, 255)'
	if (bgRaw) {
		ctx.fillStyle = bgRaw
		ctx.fillRect(0, 0, 1, 1)
	}
	if (liftRaw) {
		ctx.fillStyle = liftRaw // painted OVER the background → canvas alpha-composites
		ctx.fillRect(0, 0, 1, 1)
	}
	const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data
	return `rgb(${r}, ${g}, ${b})`
}

import { getContext, setContext } from 'svelte'

// Every Stripe payment surface needs a client_secret at confirm time:
//   - Payment Element  → confirmPayment({ elements, clientSecret })
//   - split card       → confirmCardPayment(stripe, elements, clientSecret, …)
//   - iDEAL            → confirmIdealPayment(stripe, clientSecret, …)
//   - Express Checkout → confirmPayment({ elements, clientSecret })
//
// It is deliberately a FUNCTION, not a value. Medusa deletes the cart's payment sessions on
// every total change, so a secret captured at mount is dead by the time the user reaches the
// pay button. `ensureClientSecret()` creates the session on demand — at submit, against the
// final total — mirroring what the Braintree path does with its nonce.
const KEY = Symbol('stripe-session')

export interface StripeSessionCtx {
	/** Initiate a payment session for the CURRENT cart total and return its client_secret. */
	ensureClientSecret: () => Promise<string | null>
}

export function setStripeSessionContext(ctx: StripeSessionCtx): void {
	setContext(KEY, ctx)
}

export function getStripeSessionContext(): StripeSessionCtx {
	return getContext<StripeSessionCtx>(KEY) ?? { ensureClientSecret: async () => null }
}

/**
 * Stripe payment-session helpers.
 *
 * Background — why the session is created at place-order rather than on mount:
 * Medusa DELETES a cart's payment sessions whenever the cart total changes
 * (`refreshPaymentCollectionForCartWorkflow` → `deletePaymentSessionsWorkflow`). Selecting a
 * shipping method, applying a discount, or changing a quantity therefore invalidates any
 * PaymentIntent created earlier, leaving its client_secret pointing at a canceled intent
 * ("This PaymentIntent is in a terminal state and cannot be used to initialize Elements").
 *
 * So <Elements> is created in Stripe's DEFERRED mode (`{mode:'payment', amount, currency}`)
 * with no session at all, and the intent is created once, at submit, against the final total.
 */

/** Currencies Stripe treats as having no minor unit — the amount is passed as-is. */
const ZERO_DECIMAL = new Set(['bif', 'clp', 'djf', 'gnf', 'jpy', 'kmf', 'krw', 'mga', 'pyg', 'rwf', 'ugx', 'vnd', 'vuv', 'xaf', 'xof', 'xpf'])

/** Currencies Stripe bills in thousandths. */
const THREE_DECIMAL = new Set(['bhd', 'jod', 'kwd', 'omr', 'tnd'])

/**
 * Convert a Medusa total (major units, e.g. `20.5`) to the integer minor-unit amount Stripe
 * expects (e.g. `2050`). Medusa stores prices in major units; Stripe's `amount` is always an
 * integer in the currency's smallest unit.
 */
export function toMinorUnits(total: number, currencyCode: string): number {
	const currency = (currencyCode || '').toLowerCase()
	const exponent = ZERO_DECIMAL.has(currency) ? 0 : THREE_DECIMAL.has(currency) ? 3 : 2
	// Round rather than truncate: floating-point totals like 20.499999999999996 must land on 2050.
	return Math.round(total * 10 ** exponent)
}

/**
 * Stripe rejects Elements in deferred mode unless the amount is a positive integer, so an empty
 * or zero-total cart must not attempt to mount. Callers render their loading/empty state instead.
 */
export function canMountElements(amount: number | null | undefined): amount is number {
	return typeof amount === 'number' && Number.isInteger(amount) && amount > 0
}

export function formatPrice(amount: number | null | undefined, currencyCode: string | null | undefined, locale = 'en-US'): string {
	if (amount == null || !currencyCode) return ''
	return new Intl.NumberFormat(locale, {
		style: 'currency',
		currency: currencyCode.toUpperCase()
	}).format(amount)
}
